best=[]
for n in [0.5,1,1.5,2,2.5,3]:
  for basis in ['1/t','exp','lnt']:
    g={'1/t':1/t,'exp':np.exp(-t),'lnt':np.log(t)}[basis]
    for h in ['t','t2','1']:
        hh={'t':t,'t2':t**2,'1':np.ones_like(t)}[h]
        X=np.column_stack([np.ones_like(t),g,hh*A**n,A**n,A])
        c=np.linalg.lstsq(X,dA_dt,rcond=None)[0]
        r=dA_dt-X@c
        best.append((np.mean(r**2)/np.var(dA_dt),n,basis,h,np.round(c,3)))
best.sort(key=lambda x:x[0])
